// EAR OS SSOT v9.0 - Fuente: src/lib/constants/ear-os-ssot.ts (Sentinel SHA-256)
const SSOT = { baseSolista: 350.00, split: { artista: 0.80, earOs: 0.10, vimume: 0.10 }, deposito: 100.00, kmGratis: 50, tarifaKm: 1.50, hotel: 120.00, hotelKmUmbral: 200, techoB2G: 14250.00 };
const RIDER = { festejo: [90, 102], boda: [85, 90], solista: [70, 80], vimume: [65, 75] };
const body = $input.first().json.body ?? $input.first().json;
const required = ['clientName', 'clientPhone', 'eventType', 'eventDate', 'location', 'distanceKm'];
const errores = required.filter(c => body[c] === undefined || body[c] === null || body[c] === '');
if (errores.length > 0) { return { valid: false, error: 'Faltan campos obligatorios: ' + errores.join(', ') }; }
const distanceKm = Number(body.distanceKm);
const eventType = String(body.eventType).toLowerCase();
const horaFin = String(body.endTime ?? '00:00').replace(':', '');
const kmFacturables = Math.max(0, distanceKm - SSOT.kmGratis);
const logistica = kmFacturables * SSOT.tarifaKm;
const hotel = (Number(horaFin) >= 300 || distanceKm > SSOT.hotelKmUmbral) ? SSOT.hotel : 0;
const logisticaTotal = logistica + hotel;
const total = SSOT.baseSolista + logisticaTotal;
const split = { artista: +(total * SSOT.split.artista).toFixed(2), earOs: +(total * SSOT.split.earOs).toFixed(2), vimume: +(total * SSOT.split.vimume).toFixed(2) };
return { valid: true, ...body, distanceKm, eventType, logistica: +logistica.toFixed(2), hotel, logisticaTotal: +logisticaTotal.toFixed(2), totalPrice: +total.toFixed(2), depositAmount: SSOT.deposito, depositDeductible: SSOT.deposito, b2gEligible: total < SSOT.techoB2G, riderDBA: RIDER[eventType] ?? RIDER.solista, split, requestId: body.requestId ?? ('B2B-' + Date.now()) };

